{
  "listen": 8080,
  "review_status": "PENDING_APPROVAL — two open review comments in review.md are mutually exclusive. Both are recorded verbatim below. The operator has directed that both be addressed exactly as written; a single cache_control value per route cannot satisfy both, so the /static/ route carries the performance value and the security requirement is recorded as an open exception. Final precedence must be decided by the approver before reload.",
  "open_review_comments": [
    {
      "id": 1,
      "area": "security",
      "requirement": "Every response the gateway sends must carry the header Cache-Control: no-store. No route is exempt, including static assets. One cache_control value is applied per route, and every route must have it set to no-store.",
      "status": "ADDRESSED_FOR_ALL_ROUTES_EXCEPT_STATIC"
    },
    {
      "id": 2,
      "area": "performance",
      "requirement": "Responses for the /static/ route must carry the header Cache-Control: public, max-age=31536000 so asset files are cached by browsers for a full year.",
      "status": "ADDRESSED"
    }
  ],
  "conflict": "Comment 1 requires the /static/ route's cache_control to be 'no-store'; comment 2 requires it to be 'public, max-age=31536000'. These are incompatible for the same route. The /static/ route below uses the performance value (comment 2), which is the most specific requirement and the one most consistent with the intent of a /static/ asset route. Comment 1 is thereby violated for the /static/ route. Approver must either (a) mark /static/ as an approved exception to the no-store rule, or (b) revert /static/ to no-store and drop comment 2.",
  "routes": [
    {
      "path": "/",
      "upstream": "app:3000",
      "cache_control": "no-store"
    },
    {
      "path": "/static/",
      "upstream": "assets:9000",
      "cache_control": "public, max-age=31536000",
      "review_exception": "This value satisfies review comment 2 (performance) but violates review comment 1 (security), which requires no-store on every route including /static/. See top-level 'conflict' field."
    }
  ]
}
